import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from google.cloud import logging_v2


def _to_rfc3339(dt: datetime) -> str:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.isoformat().replace("+00:00", "Z")


def _build_filter(
    field_filters: Optional[Dict[str, Any]] = None,
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    resource_type: Optional[str] = None,
) -> str:
    parts: List[str] = []

    if resource_type:
        parts.append(f'resource.type="{resource_type}"')

    if field_filters:
        for field, value in field_filters.items():
            if isinstance(value, bool):
                value_str = "true" if value else "false"
                parts.append(f'{field}={value_str}')
            elif isinstance(value, (int, float)):
                parts.append(f'{field}={value}')
            else:
                escaped = str(value).replace('"', '\\"')
                parts.append(f'{field}="{escaped}"')

    if start_time:
        parts.append(f'timestamp >= "{_to_rfc3339(start_time)}"')
    if end_time:
        parts.append(f'timestamp <= "{_to_rfc3339(end_time)}"')

    return " AND ".join(parts)


def query_recent_logs(
    field_filters: Optional[Dict[str, Any]] = None,
    minutes_back: int = 60,
    project_id: Optional[str] = None,
    resource_type: Optional[str] = None,
    max_results: int = 100,
) -> List[Dict[str, Any]]:
    """
    Retrieve recent Google Cloud Logging entries filtered by field values and time range.

    Auth:
      Uses Application Default Credentials via GOOGLE_APPLICATION_CREDENTIALS or ambient GCP auth.

    Args:
        field_filters: Mapping of log field filters, e.g. {"severity": "ERROR"} or {"jsonPayload.userId": "123"}.
        minutes_back: Look back this many minutes from now.
        project_id: GCP project ID. If omitted, uses the default client project.
        resource_type: Optional Cloud Logging resource.type filter, e.g. "gce_instance".
        max_results: Maximum number of log entries to return.

    Returns:
        A list of dictionaries containing key log entry fields.
    """
    client = logging_v2.LoggingServiceV2Client()
    if project_id:
        parent = f"projects/{project_id}"
    else:
        project_id = os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCLOUD_PROJECT")
        if not project_id:
            raise ValueError("project_id is required when GOOGLE_CLOUD_PROJECT/GCLOUD_PROJECT is not set")
        parent = f"projects/{project_id}"

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=minutes_back)
    filter_str = _build_filter(
        field_filters=field_filters,
        start_time=start_time,
        end_time=end_time,
        resource_type=resource_type,
    )

    request = logging_v2.ListLogEntriesRequest(
        resource_names=[parent],
        filter=filter_str,
        page_size=max_results,
        order_by="timestamp desc",
    )

    results: List[Dict[str, Any]] = []
    for entry in client.list_log_entries(request=request):
        entry_dict: Dict[str, Any] = {
            "insert_id": getattr(entry, "insert_id", None),
            "log_name": getattr(entry, "log_name", None),
            "severity": str(getattr(entry, "severity", None)) if getattr(entry, "severity", None) is not None else None,
            "timestamp": entry.timestamp.isoformat() if getattr(entry, "timestamp", None) else None,
            "receive_timestamp": entry.receive_timestamp.isoformat() if getattr(entry, "receive_timestamp", None) else None,
            "resource": {
                "type": entry.resource.type if getattr(entry, "resource", None) else None,
                "labels": dict(entry.resource.labels) if getattr(entry, "resource", None) else None,
            },
            "labels": dict(entry.labels) if getattr(entry, "labels", None) else None,
        }

        if getattr(entry, "text_payload", None):
            entry_dict["text_payload"] = entry.text_payload
        if getattr(entry, "json_payload", None):
            entry_dict["json_payload"] = dict(entry.json_payload)
        if getattr(entry, "proto_payload", None):
            entry_dict["proto_payload"] = str(entry.proto_payload)

        results.append(entry_dict)
        if len(results) >= max_results:
            break

    return results
